        id: el.getAttribute\('data-item-id'\),
        transform: el.getAttribute\('transform'\),
        bbox: { x: bbox.x, y: bbox.y, w: bbox.width, h: bbox.height },
        rectW: rect?.getAttribute\('width'\),
        rectH: rect?.getAttribute\('height'\),
      };
    }\);
  }\);
  rects.forEach\(r => console.log\(JSON.stringify\(r\)\)\);

  // Also get room rect bbox
  const roomBbox = await page.evaluate\(\(\) => {
    const svgRects = document.querySelectorAll\('svg rect'\);
    // Find the room rect \(stroke='#663F23', fill='none'\)
    for \(const r of svgRects\) {
      if \(r.getAttribute\('fill'\) === 'none' && r.getAttribute\('stroke'\) === '#663F23'\) {
        const bb = r.getBoundingClientRect\(\);
        return { x: bb.x, y: bb.y, w: bb.width, h: bb.height };
      }
    }
    return null;
